r":"Consumers and end users [member]","BusinessConductMember":"BusinessConductMember"},"required":true,"aria_label":"Sustainability issue addressed"},{"key":"description","label":"DescriptionOfPracticesPoliciesAndOrFutureInitiatives","type":"text","aria_label":"Description of the practice, policy or initiative"},{"key":"public","label":"PracticePolicyAndOrFutureInitiativeIsPubliclyAvailable","type":"boolean","aria_label":"Publicly available"},{"key":"target_set","label":"UndertakingHasSetATargetWhichIsRelatedToAPolicy","type":"boolean","aria_label":"A target related to this policy is set"},{"key":"senior_accountable","label":"MostSeniorLevelAccountableForImplementationOfPolicies","type":"boolean","aria_label":"A most senior level accountable for implementation is designated"}],"footer":["policies_public_count"],"note":"Unticked boxes mean \"not publicly available\" / \"no target\" / \"no senior level designated\". The one-row scalars on B02.000 (issue, public, target) and the C02.000 descriptions stay until ratified (vsme-D-12 … D-16); prod holds ONE stored value on PracticePolicyAndOrFutureInitiativeIsPubliclyAvailable (read-only count 2026-09-18) — its retirement is not data-free."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
