SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-B03.100-A'), 'energy_carriers', 'Energy consumption by carrier (one row each: carrier, MWh)', 'json', NULL, false, 'VSME B3 para 29', 'Plan 3: rows per energy carrier (the B03.100 breakdown as a register; options = the three prod symbols EnergyConsumptionFromElectricity / EnergyConsumptionFromSelfGeneratedElectricity / EnergyConsumptionFromFuels); Σ → TotalEnergyConsumption_calc (VSME-B03.100-D1). The three scalars stay (vsme-D-18 … D-20).', 'imported_unverified', 'VSME B3, §29 (p.9): "The undertaking shall disclose its total energy consumption in MWh, with a breakdown as per the table below, if it can obtain the necessary information to provide such a breakdown:" [prod verification_quote (Para 29, VSME-CR-B03-01)]', 'register', '{"title":"Energy consumption breakdown (B3 para 29)","subtitle":"one row per energy carrier — the three prod line items as options, consumption in MWh","add_label":"+ energy carrier","placement":"section","columns":[{"key":"carrier","label":"Energy carrier","type":"enum","options":["electricity","self_generated","fuels"],"option_labels":{"electricity":"EnergyConsumptionFromElectricity","self_generated":"EnergyConsumptionFromSelfGeneratedElectricity","fuels":"EnergyConsumptionFromFuels"},"required":true,"aria_label":"Energy carrier (electricity / self-generated electricity / fuels)"},{"key":"mwh","label":"Energy consumption","type":"number","unit":"MWh","min":0,"required":true,"aria_label":"Energy consumption of this carrier in MWh"}],"footer":["TotalEnergyConsumption_calc"],"note":"Σ MWh over the rows → TotalEnergyConsumption_calc (VSME-B03.100-D1), the computed twin of TotalEnergyConsumption on B03.000 (typed today; inheritance STAGED vsme-C-4, pair vsme-D-17). The three scalars EnergyConsumptionFromElectricity / …SelfGeneratedElectricity / …Fuels stay (vsme-D-18 … D-20)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'energy_carriers') AND w.code = 'VSME-B03.100' AND s.code = 'VSME';
