SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-B03.100-A'), 'TotalEnergyConsumption_calc', 'Total energy consumption (Σ MWh from the energy-carrier register)', 'number', 'MWh', false, 'VSME B3 para 29', 'Plan 3: output of equation VSME-B03.100-D1 (sum_rows of mwh over energy_carriers); computed twin of B03.000 TotalEnergyConsumption (vsme-D-17); inheritance into B03.000 STAGED (vsme-C-4).', 'imported_unverified', 'VSME B3, §29 (p.9): "The undertaking shall disclose its total energy consumption in MWh, with a breakdown as per the table below, if it can obtain the necessary information to provide such a breakdown:" [prod verification_quote (Para 29, VSME-CR-B03-01)]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
