SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-B07.300-A'), 'materials', 'Materials used (one row each: name, weight t, volume m³)', 'json', NULL, false, 'VSME B7', 'Plan 3: rows per material (the XBRL line-items table B07.300 as a register); Σ t → TotalMassOfMaterialUsed_calc (VSME-B07.300-D1), Σ m³ → TotalVolumeOfMaterialUsed_calc (-D2). The one-row scalars stay (vsme-D-25 … D-27); the B07.400 consumers are STAGED (vsme-C-8). No paragraph text of B7 materials exists in prod — vsme-U-1.', 'imported_unverified', 'Environment - Breakdown of annual mass-flow of relevant materials used by the undertaking [prod worksheet_templates.title_de (VSME-B07.300) — no paragraph text in prod; vsme-U-1]', 'register', '{"title":"Materials used (B7)","subtitle":"one row per relevant material — name, annual mass in t and/or volume in m³","add_label":"+ material","placement":"section","columns":[{"key":"name","label":"Name of the material used","type":"text","required":true,"aria_label":"Name of the material used"},{"key":"weight_t","label":"Weight of material used","type":"number","unit":"t","min":0,"aria_label":"Weight of the material used in tonnes"},{"key":"volume_m3","label":"VolumeOfMaterialUsed","type":"number","unit":"m³","min":0,"aria_label":"Volume of the material used in cubic metres"}],"footer":["TotalMassOfMaterialUsed_calc","TotalVolumeOfMaterialUsed_calc"],"note":"A material reported by mass only (or by volume only) leaves the other cell empty — an empty cell counts as 0 in the two Σ (never blocks the row). The one-row scalars NameOfMaterialUsed / WeightOfMaterialUsed / VolumeOfMaterialUsed stay (vsme-D-25 … D-27); the B07.400 totals are the consumers once vsme-C-8 is ratified (vsme-D-28 / D-29)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'materials') AND w.code = 'VSME-B07.300' AND s.code = 'VSME';
