INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-B08.200-A'), 'employees_by_country_sum', 'Number of employees (Σ over the countries of employment contract)', 'number', NULL, false, 'VSME B8 para 39', 'Plan 3: output of equation VSME-B08.200-D1 (sum_rows of count over employees_by_country).', 'imported_unverified', 'Para 39: „… shall disclose the number of employees … for the following metrics: (a) type of employment contract (temporary or permanent) …“ Unbedingt, aber als aufgeteilte Zählung (leer ≠ null) — daher beratend. [prod verification_quote (Para 39, VSME-CR-B08-01)] — Social - Workforce - General characteristics: country of employment [prod worksheet_templates.title_de (VSME-B08.200) — no paragraph text in prod; vsme-U-1]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'employees_by_country_sum') AND w.code = 'VSME-B08.200' AND s.code = 'VSME';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-B08.200-A'), 'employees_country_delta', 'Consistency: NumberOfEmployees (B01.000) − Σ employees by country (0 = consistent)', 'number', NULL, false, 'VSME B1 para 24(e); B8 para 39', 'Plan 3: output of equation VSME-B08.200-D2 (NumberOfEmployees − sum_rows(employees_by_country, count)); NumberOfEmployees is a B01.000 field (typed, also EQ-01 output) and is not inherited into B08.200 today — the value is manual_required until vsme-C-9 is ratified.', 'imported_unverified', 'Para 24(e): „… the number of employees in headcount or full-time equivalent (FTE) …“ Unbedingte Pflichtangabe; als Stammdatum beratend geführt. [prod verification_quote (Para 24(e), VSME-CR-B01-07)] — Para 39: „… shall disclose the number of employees … for the following metrics: (a) type of employment contract (temporary or permanent) …“ Unbedingt, aber als aufgeteilte Zählung (leer ≠ null) — daher beratend. [prod verification_quote (Para 39, VSME-CR-B08-01)]', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'employees_country_delta') AND w.code = 'VSME-B08.200' AND s.code = 'VSME';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-C03.300-A'), 'high_climate_impact_sector', 'Undertaking operates in a high climate impact sector (C3)', 'boolean', NULL, false, 'VSME C3', 'Plan 3: driver of the C3 transition-plan disclosures (DescriptionOfATransitionPlan… / DateOfAdoption…); the derivation from NaceSectorClassificationCodes needs the printed sector list, which is not in prod — vsme-F-2 (engineer attestation until then).', 'imported_unverified', 'Environment - Transition plan for undertakings operating in high climate impact sectors [prod worksheet_templates.title_de (VSME-C03.300) — no paragraph text in prod; vsme-U-1]', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'high_climate_impact_sector') AND w.code = 'VSME-C03.300' AND s.code = 'VSME';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'high_climate_impact_sector == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'DescriptionOfATransitionPlanForClimateChangeMitigationIncludingAnExplanationOfHowItIsContributingToReduceGhgEmissions' AND w.code = 'VSME-C03.300' AND s.code = 'VSME' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'high_climate_impact_sector == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'DateOfAdoptionOfTransitionPlanForUndertakingNotHavingAdoptedTransitionPlanYet' AND w.code = 'VSME-C03.300' AND s.code = 'VSME' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'select_one', ui_config = NULL, lookup = NULL, visible_when = 'UndertakingHasACodeOfConductOrHumanRightsPolicyForItsOwnWorkforce == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'TypeOfContentCoveredByTheCodeOfConductOrHumanRightsPolicyForItsOwnWorkforce' AND w.code = 'VSME-C06.000' AND s.code = 'VSME' AND f.active AND f.visible_when IS NULL;
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'UndertakingHasACodeOfConductOrHumanRightsPolicyForItsOwnWorkforce == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'SpecificationOfOtherTypesOfContentCoveredByTheCodeOfConductOrHumanRightsPolicy' AND w.code = 'VSME-C06.000' AND s.code = 'VSME' AND f.active AND f.visible_when IS NULL;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-C07.000-A'), 'human_rights_incidents', 'Confirmed human rights incidents (one row each: type, specification, actions)', 'json', NULL, false, 'VSME C7', 'Plan 3: rows per confirmed incident (the XBRL line-items table C07.000 as a register; type tokens = prod TypeOfHumanRightRelatedToTheConfirmedIncident). The one-row scalars stay (vsme-D-31 … D-33). No paragraph text of C7 exists in prod — vsme-U-1.', 'imported_unverified', 'Social - Severe negative human rights incidents [prod worksheet_templates.title_de (VSME-C07.000) — no paragraph text in prod; vsme-U-1]', 'register', '{"title":"Confirmed severe negative human rights incidents (C7)","subtitle":"one row per confirmed incident — type of human right, specification, actions taken","add_label":"+ incident","placement":"section","columns":[{"key":"type","label":"Type of human right related to the confirmed incident","type":"enum","options":["ChildLabourMember","ForcedLabourMember","HumanTraffickingMember","DiscriminationMember","AccidentPreventionMember","OtherContentMember"],"option_labels":{"ChildLabourMember":"Child labour [member]","ForcedLabourMember":"Forced labour [member]","HumanTraffickingMember":"Human trafficking [member]","DiscriminationMember":"Discrimination [member]","AccidentPreventionMember":"Accident prevention [member]","OtherContentMember":"Other content [member]"},"required":true,"aria_label":"Type of human right related to the confirmed incident"},{"key":"specification","label":"SpecificationOfOtherHumanRightsRelatedToTheConfirmedIncident","type":"text","aria_label":"Specification of the incident (other human rights, value-chain workers, communities, consumers)"},{"key":"actions","label":"Description of actions take to address the confirmed incidents","type":"text","aria_label":"Actions taken to address the confirmed incident"}],"note":"Rows are entered only when UndertakingHasConfirmedHumanRightsIncidentsInItsOwnWorkforce / UndertakingIsAwareOfAnyConfirmedIncidents… is yes (no rule emitted — no paragraph text in prod carries the condition, vsme-U-1). The one-row scalars stay (vsme-D-31 … D-33)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'human_rights_incidents') AND w.code = 'VSME-C07.000' AND s.code = 'VSME';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'VSME-C09.000-A'), 'governance_body_exists', 'Undertaking has a governance body in place (C9 para 65)', 'boolean', NULL, false, 'VSME C9 para 65', 'Plan 3: driver of the C9 gender-diversity disclosure („If the undertaking has a governance body in place …“); the hide of GenderDiversityRatioInGovernanceBody and the IF-guard of CR-C09-01 are STAGED together (vsme-G-3).', 'imported_unverified', 'Para 65: „If the undertaking has a governance body in place, the undertaking shall disclose the related gender diversity ratio.“ Bedingt + Comprehensive-Modul → beratend. [prod verification_quote (Para 65, VSME-CR-C09-01)]', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'governance_body_exists') AND w.code = 'VSME-C09.000' AND s.code = 'VSME';
COMMIT;
